## comando
```sh
cd /home/one/projects/one/ai-guides && git status --porcelain tooling/sonarqube_guide | head -20 && python3 - <<'EOF'
import subprocess,re
files=["08-scanners-e-analise.md","09-modelo-de-qualidade.md","10-quality-gates-e-perfis.md","11-regras-e-customizacao.md","12-web-api-e-automacao.md","13-webhooks-e-eventos.md"]
for f in files:
    old=subprocess.run(["git","show",f"HEAD:tooling/sonarqube_guide/{f}"],capture_output=True,text=True,cwd="/home/one/projects/one/ai-guides").stdout
    new=open("/home/one/projects/one/ai-guides/tooling/sonarqube_guide/"+f).read()
    def cites(s):
        return set(re.findall(r'https://docs\.sonarsource\.com/\S+?\.md',s))
    def paths(s):
        return set(re.findall(r'`([^`\s]+\.(?:java|gradle|properties|json|xml|md):[^`\s]*)`',s))
    ou,nu=cites(old),cites(new); op,np_=paths(old),paths(new)
    print(f,'urls missing:',ou-nu,'| added:',nu-ou)
    print('   paths missing:',op-np_,'| added:',np_-op)
EOF
```

